namespace AlSsareea.CustomerApp;

public abstract class StatePage : ContentPage { protected StatePage(string title, string message) { Title = title; Content = new ScrollView { Content = new VerticalStackLayout { Padding = 24, Spacing = 16, Children = { new Label { Text = title, FontSize = 28, FontAttributes = FontAttributes.Bold }, new Label { Text = message } } } }; } }
public sealed class SearchPage() : StatePage("Search", "Catalog search requires a merchant identifier; global search is not exposed by the backend."); public sealed class CartPage() : StatePage("Cart", "Authenticated cart and backend checkout summaries."); public sealed class OrdersPage() : StatePage("Orders", "Order history and details use /api/v1/orders."); public sealed class ProfilePage() : StatePage("Profile", "Profile, preferences, addresses and logout use self-service APIs."); public sealed class AddressesPage() : StatePage("Addresses", "Address mutations use the current customer endpoint."); public sealed class CheckoutPage() : StatePage("Checkout", "Backend totals and a stable order idempotency key."); public sealed class NotificationsPage() : StatePage("Notifications", "Inbox, read state, preferences and device registration."); public sealed class TrackingPage() : StatePage("Tracking", "REST resynchronization and authenticated tracking hub."); public sealed class LoginPage() : StatePage("Login", "Password login and backend OTP challenge flow.");
